INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_elect_b001_023', 'topic_was_elect_5', 'subj_wassce_elect_app', 'exam_wassce', NULL, NULL, 'What is the function of the split-ring commutator in a simple DC motor?', 'multiple_choice', NULL, '["A. Increase supply frequency","B. Store charge like a capacitor","C. Reverse armature current each half-turn to maintain torque direction","D. Disconnect the magnetic field permanently"]', 'C', 'The commutator changes current direction relative to the field so the forces continue to turn the armature in the same rotational direction. Therefore the correct answer is C: Reverse armature current each half-turn to maintain torque direction.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_elect_5', 'Identify', 'AO2', NULL, NULL, 'board_waec');
