INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_elect_b001_025', 'topic_was_elect_5', 'subj_wassce_elect_app', 'exam_wassce', NULL, NULL, 'What mainly determines the synchronous speed of an AC machine?', 'multiple_choice', NULL, '["A. Supply frequency and number of poles","B. Only the colour of the windings","C. Bearing diameter alone","D. Insulation resistance only"]', 'A', 'Synchronous speed follows 120 times frequency divided by pole count, so higher pole count lowers speed at a fixed frequency. Therefore the correct answer is A: Supply frequency and number of poles.', 'easy', '3', '3', '90', NULL, NULL, '1', NULL, 'st_was_elect_5', 'Identify', 'AO1', NULL, NULL, 'board_waec');
