INSERT INTO _migration_134_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions WHERE id IN ('q_was_elect_b001_021', 'q_was_elect_b001_022', 'q_was_elect_b001_023', 'q_was_elect_b001_024', 'q_was_elect_b001_025')) = 5 AND (SELECT COUNT(*) FROM question_content_releases r WHERE r.question_id IN ('q_was_elect_b001_021', 'q_was_elect_b001_022', 'q_was_elect_b001_023', 'q_was_elect_b001_024', 'q_was_elect_b001_025') AND r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Applied Electricity practice; not official WAEC examination material and not the new Applied Technology III bank.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2026/03/FINAL-TIMETABLE-FOR-WASSCE-SC-2026-GHANA-ONLY-NEW-TAD.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 5 THEN 1 ELSE 0 END;
